import { Accordion, SearchBox } from "march/ui"
import { truck, receipt, shieldCheck, creditCard } from "march/icons"

// yardım merkezi: arama kutusu soruları süzer; açılan soru sayılır
const faq = [
  { id: "kargo", title: "Kargom ne zaman gelir?", icon: truck, content: "Siparişler aynı gün paketlenir, 2–3 iş gününde teslim edilir." },
  { id: "iade", title: "Nasıl iade ederim?", icon: receipt, content: "Hesabım › Siparişler › İade et: etiket e-postanıza gelir." },
  { id: "garanti", title: "Garanti süresi ne kadar?", icon: shieldCheck, content: "Bütün cihazlar iki yıl garantilidir." },
  { id: "odeme", title: "Hangi ödeme yollarını kabul ediyorsunuz?", icon: creditCard, content: "Kredi kartı, banka kartı ve havale." },
]

export function HelpCenter() {
  let $q = ""
  let $opened = 0
  const shown = () => faq.filter((f) => f.title.toLocaleLowerCase("tr").includes($q.toLocaleLowerCase("tr")))
  return <div sx={{ flex: "col", gap: 3 }}>
    <SearchBox label="Soru ara" value={$q} onInput={(v: string) => $q = v} />
    {() => <Accordion variant="contained" items={shown()} onToggle={(_k: string | number, open: boolean) => { if (open) $opened++ }} />}
    <span sx={{ text: "xs", color: "muted" }}>{shown().length} soru · {$opened} kez açıldı</span>
  </div>
}

import { Accordion } from "march/ui"
import { Icon, user, bell, lock, plus, minus } from "march/icons"

// Accordion'un bütün özellikleri: items (id, title, subtitle, icon, content, disabled), multiple, open, variant,
// chevron (kendi işaretin, işlev ya da yok), animated, onToggle, class ve m:color
export function AccordionLab() {
  let $log = "henüz yok"
  const items = [
    { id: "profil", title: "Profil", subtitle: "Ad, fotoğraf", icon: user, content: "Adınızı ve fotoğrafınızı değiştirin." },
    { id: "bildirim", title: "Bildirimler", subtitle: "E-posta, anlık", icon: bell, content: "Hangi olaylarda haber verilsin?" },
    { id: "guvenlik", title: "Güvenlik", icon: lock, content: "İki adımlı doğrulama", disabled: true },
  ]
  return <div sx={{ flex: "col", gap: 4 }}>
    <Accordion items={items} multiple open={["profil", "bildirim"]} variant="contained" class="lab-acc"
      chevron={(open: () => boolean) => <span>{() => <Icon of={open() ? minus : plus} />}</span>}
      onToggle={(k: string | number, open: boolean) => $log = `${k} ${open ? "açıldı" : "kapandı"}`} />
    <span sx={{ text: "sm", color: "muted" }}>Son olay: {$log}</span>
    <Accordion items={items.slice(0, 2)} chevron={false} animated={false} m:color="brand-purple" />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { AccordionLab } from "./AccordionLab.tsx"

// AccordionLab'in testleri: kaydedince Testler sekmesinde çalışır
test("open ile verilen iki bölüm baştan açık (multiple)", () => {
  const s = renderTest(() => <AccordionLab />)
  const heads = s.all(".lab-acc .m-acc-btn")
  expect(heads[0]?.getAttribute("aria-expanded")).toBe("true")
  expect(heads[1]?.getAttribute("aria-expanded")).toBe("true")
})

test("başlığa basınca bölüm kapanır ve onToggle olayı yazar", async () => {
  const s = renderTest(() => <AccordionLab />)
  await s.click(s.all(".lab-acc .m-acc-btn")[0]!)
  expect(s.all(".lab-acc .m-acc-btn")[0]?.getAttribute("aria-expanded")).toBe("false")
  expect(s.text()).toContain("profil kapandı")
})

test("disabled bölümün başlığı devre dışı", () => {
  const s = renderTest(() => <AccordionLab />)
  expect((s.all(".lab-acc .m-acc-btn")[2] as HTMLButtonElement).disabled).toBe(true)
})

test("chevron={false} ok çizmez", () => {
  const s = renderTest(() => <AccordionLab />)
  const plain = s.all(".m-accordion")[1]!
  expect(plain.querySelector(".m-acc-chev")).toBe(null)
})
